/// Any concrete kind of XML type `com:SpecialDay`, chosen by `xsi:type`.
#[derive(Debug, Clone, PartialEq)]
pub enum AnySpecialDay {
    /// XML type `com:SpecialDay`.
    SpecialDay(Box<SpecialDay>),
    /// XML type `com:PublicHoliday`.
    PublicHoliday(Box<PublicHoliday>),
}

impl AnySpecialDay {
    pub(crate) fn read(r: &mut Xml<'_>) -> Result<Option<Self>, Error> {
        Self::read_as(r, r.xsi_type())
    }

    pub(crate) fn read_as(r: &mut Xml<'_>, kind: Option<u32>) -> Result<Option<Self>, Error> {
        Ok(Some(match kind {
            Some(0x301e4) => Self::SpecialDay(Box::new(SpecialDay::read(r)?)),
            Some(0x3019c) => Self::PublicHoliday(Box::new(PublicHoliday::read(r)?)),
            None => Self::SpecialDay(Box::new(SpecialDay::read(r)?)),
            _ => {
                r.unknown_type_as("SpecialDay");
                Self::SpecialDay(Box::new(SpecialDay::read(r)?))
            }
        }))
    }

    /// XML element `com:intersectWithApplicableDays`, which every kind has.
    pub fn intersect_with_applicable_days(&self) -> Option<&Boolean> {
        match self {
            Self::SpecialDay(v) => v.intersect_with_applicable_days.as_ref(),
            Self::PublicHoliday(v) => v.intersect_with_applicable_days.as_ref(),
        }
    }

    /// XML element `com:specialDayType`, which every kind has.
    pub fn special_day_type(&self) -> Option<&SpecialDayTypeEnum> {
        match self {
            Self::SpecialDay(v) => v.special_day_type.as_ref(),
            Self::PublicHoliday(v) => v.special_day_type.as_ref(),
        }
    }

    /// XML element `com:publicEvent`, which every kind has.
    pub fn public_event(&self) -> Option<&PublicEventTypeEnum> {
        match self {
            Self::SpecialDay(v) => v.public_event.as_ref(),
            Self::PublicHoliday(v) => v.public_event.as_ref(),
        }
    }

    /// XML element `com:namedArea`, which every kind has.
    pub fn named_area(&self) -> &[NamedArea] {
        match self {
            Self::SpecialDay(v) => &v.named_area,
            Self::PublicHoliday(v) => &v.named_area,
        }
    }

    /// XML element `com:_specialDayExtension`, which every kind has.
    pub fn special_day_extension(&self) -> Option<&Extension> {
        match self {
            Self::SpecialDay(v) => v.special_day_extension.as_deref(),
            Self::PublicHoliday(v) => v.special_day_extension.as_deref(),
        }
    }
}

impl AnySpecialDay {
    pub(crate) fn write(&self, w: &mut Out<'_>, tag: &'static str) -> Result<(), Error> {
        match self {
            Self::SpecialDay(v) => v.write(w, tag, "", ""),
            Self::PublicHoliday(v) => v.write(w, tag, " xsi:type=\"com:PublicHoliday\"", ""),
        }
    }
}

